--
-- Keyed on @(rail, codstatus, txtreason)@ because @codstatus@ alone is not a reason:
-- \"Invalid Account No\" appears under four different codes on the same rail. The code says
-- whether it failed; the text says why.
module Kernel.External.Payout.HdfcCbx.StatusMap
  ( StatusCategory (..),
    statusCategory,
    isTerminal,
  )
where

import qualified Data.Map.Strict as Map
import Kernel.Prelude

data StatusCategory
  = -- | Not finished. Keep inquiring while budget remains.
    Interim
  | -- | Settled. Terminal.
    Processed
  | -- | Failed. Terminal.
    Rejected
  deriving stock (Show, Read, Eq, Ord, Generic)

isTerminal :: StatusCategory -> Bool
isTerminal Interim = False
isTerminal _ = True

-- | An unknown combination returns 'Nothing'. The caller must treat that as 'Interim' and
-- raise an alert -- never as success or failure. Guessing either pays twice or strands a
-- balance, and HDFC do reissue this sheet.
statusCategory :: Text -> Text -> Text -> Maybe StatusCategory
statusCategory rail codstatus txtreason =
  Map.lookup (rail, codstatus, txtreason) table

